import { flyGeospatialCameraToAsync } from "@babylonjs/lite";
import type { GeospatialCamera, SceneContext } from "@babylonjs/lite";

export interface Place { yaw: number; pitch: number; radius: number; center: { x: number; y: number; z: number } }

const activeFlights = new WeakMap<GeospatialCamera, { cancelled: boolean; settled: boolean; wrapper: (() => void) | undefined; previous: (() => void) | undefined }>();

export function flyToPlace(camera: GeospatialCamera, scene: SceneContext, place: Place, durationMs: number): Promise<boolean> {
  const previous = activeFlights.get(camera);
  if (previous && !previous.settled) {
    previous.cancelled = true;
  }
  // Stop whatever fly is currently registered, if any.
  const currentCancel = camera._cancelFly;
  if (typeof currentCancel === "function") {
    currentCancel();
  }

  const state = { cancelled: false, settled: false, wrapper: undefined as (() => void) | undefined, previous: camera._cancelFly };
  const wrapper = () => {
    if (!state.settled) state.cancelled = true;
    const prev = state.previous;
    if (typeof prev === "function" && prev !== wrapper) prev();
  };
  state.wrapper = wrapper;
  camera._cancelFly = wrapper;
  activeFlights.set(camera, state);

  const flyPromise = flyGeospatialCameraToAsync(camera, scene, {
    yaw: place.yaw,
    pitch: place.pitch,
    radius: place.radius,
    center: place.center,
    durationMs: Math.max(0, durationMs),
  });

  // If the library installed its own cancel handler after we set ours, wrap it instead of losing ours.
  // But if we do this synchronously, we may overwrite library's cancel with wrapper again.
  if (camera._cancelFly !== wrapper) {
    state.previous = camera._cancelFly;
    camera._cancelFly = wrapper;
  }

  return flyPromise.then(
    () => !state.cancelled,
    () => false,
  ).finally(() => {
    state.settled = true;
    if (camera._cancelFly === wrapper) {
      camera._cancelFly = state.previous;
    }
    if (activeFlights.get(camera) === state) {
      activeFlights.delete(camera);
    }
  });
}
```
