import type { GeospatialCamera, SceneContext } from "@babylonjs/lite";

export interface Place {
  yaw: number;
  pitch: number;
  radius: number;
  center: { x: number; y: number; z: number };
}

interface FlightState {
  cancelled: boolean;
  settled: boolean;
  wrapper: (() => void) | undefined;
  underlying: (() => void) | undefined;
  settle: (arrived: boolean) => void;
  cancel: () => void;
}

const activeFlights = new WeakMap<GeospatialCamera, FlightState>();

export function flyToPlace(camera: GeospatialCamera, scene: SceneContext, place: Place, durationMs: number): Promise<boolean> {
  const previous = activeFlights.get(camera);
  if (previous && !previous.settled) {
    previous.cancel();
  }

  const state: FlightState = {
    cancelled: false,
    settled: false,
    wrapper: undefined,
    underlying: undefined,
    settle: () => {},
    cancel: () => {},
  };

  const promise = new Promise<boolean>((resolve) => {
    state.settle = (arrived: boolean) => {
      if (state.settled) return;
      state.settled = true;
      resolve(arrived);

      if (camera._cancelFly === state.wrapper) {
        camera._cancelFly = state.underlying;
      }
      if (activeFlights.get(camera) === state) {
        activeFlights.delete(camera);
      }
    };
  });

  // Stop any fly that is currently registered on the camera, even if it was not started through flyToPlace.
  const currentCancel = camera._cancelFly;
  if (typeof currentCancel === "function") {
    currentCancel();
  }

  let flyPromise: Promise<void>;
  try {
    flyPromise = flyGeospatialCameraToAsync(camera, scene, {
      yaw: place.yaw,
      pitch: place.pitch,
      radius: place.radius,
      center: place.center,
      durationMs: Number.isFinite(durationMs) ? Math.max(0, durationMs) : 0,
    });
  } catch {
    state.settle(false);
    return promise;
  }

  state.underlying = camera._cancelFly;
  const wrapper = () => {
    if (!state.settled) {
      state.cancelled = true;
      const underlying = state.underlying;
      if (typeof underlying === "function" && underlying !== wrapper) {
        underlying();
      }
      state.settle(false);
    }
  };
  state.wrapper = wrapper;
  state.cancel = () => {
    if (!state.settled) {
      state.cancelled = true;
      const underlying = state.underlying;
      if (typeof underlying === "function" && underlying !== wrapper) {
        underlying();
      }
      state.settle(false);
    }
  };
  camera._cancelFly = wrapper;
  activeFlights.set(camera, state);

  flyPromise.then(
    () => {
      if (!state.settled) {
        state.settle(!state.cancelled);
      }
    },
    () => {
      state.settle(false);
    }
  );

  return promise;
}
